/**
 * PO-match explanation client (DOCB-14348).
 *
 * Reads the three `po-match-explanation` routes, which answer the same
 * question at three scopes and return ONE envelope:
 *
 *   ruleset  -> how this organisation matches, with no document at all
 *   document -> the path ONE document took through the five stages
 *   cluster  -> where the documents of one recurring issue stop
 *
 * Extends `TouchlessService` rather than `AbstractApiService` for the reason
 * `PipelineExplanationService` (DOCB-14351) does: `subOrgScopeQuery()` is the
 * client-side half of the DOCB-14288 chokepoint, and a second implementation
 * of it here would be one refactor away from asking the backend for a
 * different population than every other widget on the same page.
 *
 * THE SHAPE OF THE DIAGRAM IS NOT DEFINED HERE. The five stages, their three
 * passes and the rules inside them arrive in `stages[]` from the API, which
 * reads them off the customer's published rule set. Anything in this file
 * that listed a stage, a pass or a rule would be a second opinion about a
 * customer's configuration — and the whole point of the feature is that there
 * is only one.
 */

import TouchlessService from 'src/services/analytics/TouchlessService';
import { DOC2API_URL } from 'src/pages/APIs';
import type { MetricEnvelope } from 'src/services/analytics/TouchlessService';

/** The three scopes one envelope can describe. */
export type PoMatchMode = 'ruleset' | 'document' | 'cluster';

/**
 * The state of a stage or of one of its passes on the taken path.
 *
 * Three values, not five: the reader is asking "did this comparison happen,
 * and did it hold". `null` is a fourth, legitimate answer and means there is
 * no path to draw — the rule-set view, or a document with no trace.
 *
 * Typed as a union PLUS `string` so a backend that adds a state renders as
 * something truthful rather than crashing a diagram.
 */
export type PoMatchState = 'pass' | 'fail' | 'skip' | string;

/** A bilingual text, as every label and sentence arrives from the API. */
export interface PoMatchText {
  en: string;
  de: string;
}

/** Where a configured value came from. */
export type PoMatchSource = 'ruleset' | 'engine_default' | string;

/**
 * One tolerance, with the key that DECIDES named separately from the key to
 * change. When a column override is unset, `effective_setting` is the generic
 * key whose number is actually in force — showing only one of the two would
 * either hide an override or invent a value for an empty field.
 */
export interface PoMatchTolerance {
  setting: string;
  effective_setting: string | null;
  value: number | null;
  type: string | null;
  configured: boolean;
  source: PoMatchSource;
  formatted: string | null;
  /**
   * Which LAYER holds the amount (DOCB-14564): `attribute` while
   * CUSTOM_RANGE_FOR_PO_TOLERANCE is on and the engine precomputes this
   * column's tolerance from the document-type attribute, `ruleset` when the
   * rule set's key is what the engine reads, `null` when the gate was not
   * read. Absent from older backends.
   */
  decided_by?: 'attribute' | 'ruleset' | null;
  /**
   * The rule-set key the attribute overrides, carried along so the reader
   * still finds the number the TOML holds — marked as not in force.
   */
  ruleset?: {
    setting: string;
    effective_setting: string | null;
    value: number | null;
    in_force: boolean;
  } | null;
}

export interface PoMatchSetting {
  key: string;
  value: number | string | null;
  configured: boolean;
  source: PoMatchSource;
  effective_value: number | string | null;
  effective_setting: string | null;
  tolerance_type?: string | null;
  formatted?: string | null;
  /**
   * Whether the engine reads this key for some column today (DOCB-14564).
   * `false` while the gate hands the amount to the attribute; `null` when it
   * cannot be known (gate unread, no rule set, unparsed rule set).
   */
  in_force?: boolean | null;
}

/** The switch that says which layer holds the tolerance AMOUNT (DOCB-14564). */
export interface PoMatchToleranceGate {
  key: string;
  value: boolean | null;
  source: PoMatchSource;
  amount_decided_by: 'attribute' | 'ruleset' | null;
}

/** One compared column pair of a rule: PO side against extracted table side. */
export interface PoMatchColumn {
  po_column: string | null;
  extracted_table_column: string | null;
  comparison_type: string | null;
  allow_tolerance: boolean;
  tolerance: PoMatchTolerance | null;
}

export interface PoMatchRule {
  name: string | null;
  type: string;
  priority: number | null;
  auto_match: boolean;
  manual_match: boolean;
  is_fallback: boolean;
  activation_conditions: unknown[];
  columns: PoMatchColumn[];
}

/** A column that rejected line pairs in one pass, worst deviation attached. */
export interface PoMatchFailedColumn {
  column: string;
  column_key: string;
  role: string;
  count: number;
  rule: string | null;
  po_column: string | null;
  extracted_table_column: string | null;
  expected: string | number | null;
  actual: string | number | null;
  tolerance: string | number | null;
  tolerance_type: string | null;
  delta: string | number | null;
  delta_pct: string | number | null;
}

export interface PoMatchPass {
  /** Recorded rule attempts, not the currently configured rules. */
  attempts?: Array<{
    rule: string | null;
    activation_matched: boolean | null;
    activation_failures: number | null;
    pairs_evaluated: number | null;
    matched: number | null;
  }>;
  key: string;
  label: PoMatchText;
  /** False when the engine does not run this pass in this stage at all. */
  runs: boolean;
  state: PoMatchState | null;
  skipped_reason: string | null;
  skipped_reason_label: PoMatchText | null;
  matched: number | null;
  pairs_evaluated: number | null;
  failed_columns: PoMatchFailedColumn[];
  /** Cluster mode only. */
  doc_count: number | null;
  share_pct: number | null;
}

export interface PoMatchStage {
  key: string;
  /** 1-based position in the engine's own stage order, sent by the API. */
  no: number;
  label: PoMatchText;
  condition: PoMatchText;
  rules: PoMatchRule[];
  rule_names: string[];
  state: PoMatchState | null;
  skipped_reason: string | null;
  skipped_reason_label: PoMatchText | null;
  matched_after_stage: number | null;
  pending_po_lines_after: number | null;
  pending_table_lines_after: number | null;
  doc_count: number | null;
  share_pct: number | null;
  passes: PoMatchPass[];
}

export interface PoMatchRuleset {
  attribute_key: string;
  doc_type: string | null;
  version: number | null;
  revision: string | null;
  hash: string | null;
  short_hash: string | null;
  published_at: string | null;
  source_org: 'org' | 'default' | string | null;
  settings_deep_link: string;
  parse_error: string | null;
  /** Absent from older backends. */
  tolerance_gate?: PoMatchToleranceGate | null;
  /**
   * Which of five situations the governing rule set is in.
   *
   * `none_published` and `unreadable` are the pair worth having a field for:
   * both arrive as a `parse_error`, and they mean opposite things. "Nobody
   * activated a version" is answered on the settings page in two clicks;
   * "the active TOML will not parse" needs a developer. A panel that showed
   * one sentence for both would send a customer to the wrong place.
   */
  state?:
    | 'published'
    | 'none_published'
    | 'unreadable'
    | 'legacy'
    | 'unknown'
    | string;
  state_label?: PoMatchText | null;
  settings: Record<string, PoMatchSetting>;
}

/**
 * The plain-language answer, twice: as the DATA it is made of, and as the
 * sentence the API composed from exactly those fields.
 *
 * A component may render `text` or build its own wording from `fields`. What
 * it must not do is add a value that is not in `fields` — an explanation with
 * one invented number in it is worse than no explanation.
 */
export interface PoMatchExplanationFields {
  stage: string | null;
  stage_no: number | null;
  stage_label: PoMatchText | null;
  rule: string | null;
  column: string | null;
  column_role: string | null;
  failed_pairs: number | null;
  expected: number | null;
  actual: number | null;
  tolerance: number | null;
  tolerance_type: string | null;
  delta_pct: number | null;
  pass: string | null;
  discarded_in_pass: PoMatchText | null;
  ruleset_version: number | null;
  matched_groups: number | null;
  unmatched_po_lines: number | null;
  unmatched_table_lines: number | null;
}

export interface PoMatchExplanationBlock {
  fields: Partial<PoMatchExplanationFields>;
  text: PoMatchText;
  /** True only when the sentence names a column AND both values. */
  complete: boolean;
}

export interface PoMatchStopPoint {
  stage: string;
  stage_no: number;
  stage_label: PoMatchText;
  pass: string | null;
  pass_label: PoMatchText | null;
  count: number;
}

export interface PoMatchDistribution {
  sampled_doc_count: number;
  attributed_count: number;
  /** Documents whose stage result carried no usable stop point. */
  unattributed_count: number;
  by_stop_stage: Record<string, number>;
  by_stop_point: PoMatchStopPoint[];
  by_failing_column: Record<string, number>;
  /**
   * Owned by the PO-match advisor evidence (DOCB-14347), not by this
   * endpoint: replaying the trace at other tolerances is that ticket's job.
   * Always `null` here today, and `would_pass_curve_reason` says why — an
   * absent field could not be told apart from a computed-as-empty one, and
   * the difference decides whether a chart or an explanation is shown.
   */
  would_pass_curve: unknown[] | null;
  would_pass_curve_reason: string;
}

export interface PoMatchTerminal {
  key: 'match_successful' | 'no_match_found' | string;
  label: PoMatchText;
}

export interface PoMatchOutcome {
  po_match_status: string | null;
  matched_groups: number;
  stop_stage: string | null;
  stop_stage_no: number | null;
  unresolved_stage: string | null;
  unmatched_po_lines: number;
  unmatched_table_lines: number;
}

export interface PoMatchExplanationResponse extends MetricEnvelope {
  mode: PoMatchMode;
  doc_id: string | null;
  issue_signature: string | null;
  /** `rules`, `legacy` or `unknown` — never guessed from a current setting. */
  engine: string | null;
  configured_engine: string | null;
  /**
   * Optional on purpose: `isValidPoMatchResponse` only guarantees `stages`,
   * so every read of this block in the template is optional-chained. A
   * response that lost its rule set is a smaller panel, not a render error.
   */
  ruleset?: PoMatchRuleset;
  stages: PoMatchStage[];
  /** Document mode only: what the transformation rules did before matching. */
  transformation?: unknown;
  terminal: PoMatchTerminal | null;
  outcome: PoMatchOutcome | null;
  trace: Record<string, unknown> | null;
  trace_missing_reason: string | null;
  trace_missing_label: PoMatchText | null;
  explanation: PoMatchExplanationBlock | null;
  distribution: PoMatchDistribution | null;
  document?: Record<string, unknown>;
}

/**
 * Is this a response the diagram can draw?
 *
 * Deliberately narrow: `stages` must be an array. Everything else the
 * component reads is optional-chained, because a missing `distribution`, a
 * missing `explanation` or a missing `terminal` is a smaller panel and not a
 * broken one — while a missing `stages` array is no diagram at all and has to
 * be caught here rather than as a render error.
 */
export function isValidPoMatchResponse(
  value: unknown,
): value is PoMatchExplanationResponse {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<PoMatchExplanationResponse>;
  return Array.isArray(candidate.stages);
}

/**
 * One bilingual text, in the reader's language, falling back to English.
 *
 * The API sends both languages for every label and for the explanation
 * sentence, so this never translates — it only picks. That is why the
 * explanation needs no Tolgee key: it is composed server-side from a closed
 * vocabulary, and a key per possible sentence could not exist.
 */
export function pickPoMatchText(
  text: PoMatchText | null | undefined,
  locale: string,
): string {
  if (!text) return '';
  const language = String(locale || '')
    .toLowerCase()
    .startsWith('de')
    ? 'de'
    : 'en';
  return text[language] || text.en || text.de || '';
}

export default class PoMatchExplanationService extends TouchlessService {
  /**
   * The API prefix, read from the same constant the rest of the panel uses so
   * a base-URL change cannot leave these routes behind.
   */
  private poMatchBase(): string {
    return `${DOC2API_URL}/api/automation-intelligence/v1`;
  }

  /**
   * How this organisation matches — the rule set, with no document.
   *
   * The read that must work first: a consultant asking "how does this
   * customer match?" has no document in hand, and the answer must not depend
   * on finding one.
   */
  public async getRuleset(
    docType = 'INVOICE',
  ): Promise<PoMatchExplanationResponse> {
    const endpoint =
      `${this.poMatchBase()}/po-match-explanation` +
      `?doc_type=${encodeURIComponent(docType)}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /** Why ONE document did or did not come through PO matching. */
  public async getDocument(docId: string): Promise<PoMatchExplanationResponse> {
    const endpoint =
      `${this.poMatchBase()}/documents/${encodeURIComponent(docId)}` +
      '/po-match-explanation';
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Where the documents of one recurring issue stop matching.
   *
   * Carries the sub-organisation scope for the reason every other read on
   * this panel does (DOCB-14288): the bars are counts, the counts are links,
   * and a bar the reader cannot open is not a bar this page may promise.
   */
  public async getCluster(
    signature: string,
    windowDays = 30,
  ): Promise<PoMatchExplanationResponse> {
    const endpoint =
      `${this.poMatchBase()}/issues/${encodeURIComponent(signature)}` +
      `/po-match-explanation?window=${encodeURIComponent(windowDays)}` +
      (await this.subOrgScopeQuery());
    return await this.getWithoutOrgId(endpoint);
  }
}
